WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure DESC, id) AS rank_in_group FROM device_readings QUALIFY rank_in_group = 1) SELECT device_code, APPROX_PERCENTILE(status_bits, ARRAY(0.25, 0.5, 0.75)) AS status_bits_quartiles, COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END) AS dv_03_count, MIN(reading_ts) AS first_seen, BIT_AND(status_bits) AS status_bits_bit_and, SIZE(COLLECT_SET(device_code)) AS num_device_codes, PERCENTILE_APPROX(humidity, ARRAY(0.25, 0.5, 0.75)) AS humidity_quartiles FROM latest GROUP BY device_code HAVING COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END) < 1 ORDER BY dv_03_count DESC;
